The spiral
First, let us reproduce the idea without animation. Every year becomes a polar line and every position around the circle represents a month.

year_series &lt;- temperature_data |&gt;
  arrange(year, date) |&gt;
  group_split(year) |&gt;
  map(function(year_data) {
    list(
      name = as.character(first(year_data$year)),
      data = year_data$median,
      color = first(year_data$year_color)
    )
  })


spiral_chart &lt;- highchart() |&gt;
  hc_chart(polar = TRUE, type = "line") |&gt;
  hc_title(text = "Global temperature anomalies by year") |&gt;
  hc_subtitle(text = "Each turn of the spiral represents January to December") |&gt;
  hc_xAxis(
    categories = month.abb,
    tickmarkPlacement = "on",
    lineWidth = 0
  ) |&gt;
  hc_yAxis(
    title = list(text = NULL),
    labels = list(format = "{value} °C")
  ) |&gt;
  hc_plotOptions(
    series = list(
      marker = list(enabled = FALSE),
      lineWidth = 1,
      animation = FALSE
    )
  ) |&gt;
  hc_add_series_list(year_series) |&gt;
  hc_legend(enabled = FALSE) |&gt;
  hc_tooltip(
    headerFormat = "&lt;b&gt;{series.name}&lt;/b&gt;&lt;br&gt;",
    pointFormat = "{point.category}: {point.y:.2f} °C"
  ) |&gt;
  hc_credits(enabled = FALSE)

spiral_chart





Without the animation, the spiral loses much of its rhetorical force. We can restore that component by creating the series as transparent lines and revealing them one by one.

animated_year_series &lt;- temperature_data |&gt;
  arrange(year, date) |&gt;
  group_split(year) |&gt;
  map(function(year_data) {
    list(
      name = as.character(first(year_data$year)),
      data = year_data$median,
      color = "transparent",
      enableMouseTracking = FALSE,
      custom = list(revealColor = first(year_data$year_color))
    )
  })


Codeanimated_spiral &lt;- highchart() |&gt;
  hc_chart(
    polar = TRUE,
    type = "line",
    events = list(
      load = htmlwidgets::JS(
        "function () {
          var chart = this;
          var duration = 16000;
          var interval = duration / chart.series.length;

          chart.series.forEach(function (series, index) {
            window.setTimeout(function () {
              series.update({
                color: series.options.custom.revealColor,
                enableMouseTracking: true
              }, false);
              chart.setTitle({ text: series.name });
              chart.redraw();
            }, 900 + index * interval);
          });
        }"
      )
    )
  ) |&gt;
  hc_title(text = "Animated spiral") |&gt;
  hc_subtitle(text = "Years appear in chronological order") |&gt;
  hc_xAxis(
    categories = month.abb,
    tickmarkPlacement = "on",
    lineWidth = 0
  ) |&gt;
  hc_yAxis(
    title = list(text = NULL),
    labels = list(format = "{value} °C")
  ) |&gt;
  hc_plotOptions(
    series = list(
      marker = list(enabled = FALSE),
      lineWidth = 1,
      animation = FALSE
    )
  ) |&gt;
  hc_add_series_list(animated_year_series) |&gt;
  hc_legend(enabled = FALSE) |&gt;
  hc_tooltip(
    headerFormat = "&lt;b&gt;{series.name}&lt;/b&gt;&lt;br&gt;",
